-- Ejecutar una sola vez en el editor SQL de un proyecto Supabase nuevo.
-- Datos y procedimientos viven en PostgreSQL; el navegador usa solamente la clave publicable.
create table public.perfiles (id uuid primary key references auth.users(id) on delete cascade, rol text not null check (rol in ('admin','analista','call')));
create table public.droguerias (codigo text primary key, nombre text not null default '', responsable text not null default '', telefono text not null default '', direccion text not null default '', municipio text not null default '', departamento text not null default '', latitud double precision, longitud double precision);
create table public.planes (id bigint generated always as identity primary key, codigo text not null references public.droguerias, modulo text not null, nivel text not null, estado_general text not null);
create table public.profesionales (id text primary key, nombre text not null, regional text not null default '', ciudad text not null default '', meta_360 integer default 0, meta_dep integer default 0, meta_admin integer default 0, activo boolean not null default true);
create table public.catalogo_actividades (id text primary key, nombre text not null, grupo text not null, meta text not null, activa boolean not null default true, requiere_tema boolean not null default false);
create table public.parametros (clave text primary key, valor jsonb not null);
create sequence public.campana_seq;
create sequence public.cobro_seq;
create table public.campanas (id text primary key default ('CAMP-'||lpad(nextval('public.campana_seq')::text,6,'0')), nombre text not null, tipo text not null, tema text not null check (tema in ('Ventas','Finanzas','Inventarios','Marketing')), nivel text not null check (nivel in ('Básico','Intermedio','Avanzado')), ciudad text not null, direccion_evento text default '', lat double precision, lng double precision, fecha date not null, jornada text not null check(jornada in ('AM','PM','Día completo')), id_profesional text not null references public.profesionales, cupos integer not null check(cupos>0), modo_segmentacion text not null check(modo_segmentacion in ('DISTANCIA','CODIGOS')), rango double precision, modo_busqueda text, estado text not null default 'Programada', creado timestamptz not null default now(), actualizado timestamptz not null default now(), check(modo_segmentacion='CODIGOS' or (lat between -90 and 90 and lng between -180 and 180 and rango>0 and modo_busqueda in ('km','min'))));
create table public.campana_base (id_campana text not null references public.campanas on delete cascade, codigo text not null references public.droguerias, nombre text not null default '', responsable text not null default '', telefono text not null default '', municipio text not null default '', distancia_km numeric, tiempo_min integer, observaciones text not null default '', tipificacion text not null default '', subtipificacion text not null default '', gestionado_por text not null default '', confirma text not null default 'Pendiente', asistencia text not null default '', fecha_gestion timestamptz, primary key(id_campana,codigo));
create table public.agenda_profesional (id text primary key, id_profesional text not null references public.profesionales, fecha date not null, jornada text not null, catalogo_id text references public.catalogo_actividades, tipo text not null, grupo text not null, meta text not null, tema text not null, nivel text not null, titulo text not null, estado text not null default 'Programado', origen text not null default 'Campaña', id_campana text unique references public.campanas on delete cascade);
create table public.asistencia_modulo (codigo text not null references public.droguerias, tema text not null, nivel text not null, id_campana text not null references public.campanas, fecha date not null, primary key(codigo,tema,nivel));
create table public.cobros (id text primary key default ('COB-'||lpad(nextval('public.cobro_seq')::text,6,'0')), fecha date not null default current_date, codigo text not null references public.droguerias, concepto text not null, valor numeric not null check(valor>=0), id_campana text not null references public.campanas, estado text not null default 'Pendiente', unique(codigo,concepto,id_campana));
insert into public.catalogo_actividades values ('ACT-360','Entrenamiento 360','ent','ent360',true,true);
insert into public.parametros values ('UMBRAL_COBERTURA','80'),('COBRO_INASISTENCIA','150000'),('COBRO_INCOMPLETO','200000'),('ESTADOS_PLAN_ABIERTO','["abierto"]'),('BLOQUEAR_DEUDA','true'),('MINUTOS_POR_KM','2.8'),('MINUTOS_BASE','5'),('TIPIFICACIONES','{"Contactado":["Confirma asistencia","No puede asistir","Reagendar"],"No contactado":["No contesta","Buzón","Número inválido"],"No interesa":["Sin personal","Cerrado","Otro"],"Agendado":["Confirmado","Lista de espera"]}');
create function public.e360_rol() returns text language sql stable security definer set search_path=public as $$ select rol from public.perfiles where id=auth.uid() $$;
create function public.e360_exigir(roles text[]) returns void language plpgsql stable security definer set search_path=public as $$ begin if auth.uid() is null or not coalesce(public.e360_rol()=any(roles),false) then raise exception 'Usuario sin permisos.'; end if; end $$;
-- Ninguna tabla se expone directamente; todas las operaciones pasan por procedimientos autorizados.
do $$ declare t text; begin foreach t in array array['perfiles','droguerias','planes','profesionales','catalogo_actividades','parametros','campanas','campana_base','agenda_profesional','asistencia_modulo','cobros'] loop execute format('alter table public.%I enable row level security',t); revoke all on table public.perfiles,public.droguerias,public.planes,public.profesionales,public.catalogo_actividades,public.parametros,public.campanas,public.campana_base,public.agenda_profesional,public.asistencia_modulo,public.cobros from anon,authenticated; end loop; end $$;
create function public.e360_droguerias() returns table(codigo text,nombre text,responsable text,telefono text,municipio text,latitud double precision,longitud double precision,plan text,elegible boolean,motivo text) language sql stable security definer set search_path=public as $$
 select d.codigo,d.nombre,d.responsable,d.telefono,d.municipio,d.latitud,d.longitud,case when p.bloqueado then 'Abierto' else 'Sin bloqueo' end,not(p.bloqueado or p.deuda),case when p.bloqueado then 'Plan abierto' when p.deuda then 'Deuda pendiente' else '' end
 from public.droguerias d cross join lateral (select exists(select 1 from public.planes x where x.codigo=d.codigo and lower(trim(x.estado_general)) in (select lower(value) from jsonb_array_elements_text((select valor from public.parametros where clave='ESTADOS_PLAN_ABIERTO')))) bloqueado, ((select valor::text::boolean from public.parametros where clave='BLOQUEAR_DEUDA') and exists(select 1 from public.cobros x where x.codigo=d.codigo and x.estado='Pendiente')) deuda) p
$$;
create function public.e360_vista_previa(p_input jsonb) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare mode text:=p_input->>'Modo_segmentacion'; result jsonb; missing jsonb; requested int; lat double precision; lng double precision; rango double precision; busq text;
begin perform public.e360_exigir(array['admin','analista']);
 if mode='CODIGOS' then
  with codes as (select distinct trim(value) codigo from jsonb_array_elements_text(coalesce(p_input->'Codigos','[]')) where trim(value)<>''), joined as (select d.* from codes c join public.e360_droguerias() d using(codigo)) select coalesce(jsonb_agg(jsonb_build_object('Codigo',codigo,'Nombre',nombre,'Responsable',responsable,'Telefono',telefono,'Municipio',municipio,'Plan',plan,'Elegible',elegible,'Motivo',motivo,'EnBase',elegible)),'[]') into result from joined;
  select coalesce(jsonb_agg(c.codigo),'[]'),count(*) into missing,requested from (select distinct trim(value) codigo from jsonb_array_elements_text(coalesce(p_input->'Codigos','[]')) where trim(value)<>'') c where not exists(select 1 from public.droguerias d where d.codigo=c.codigo);
  requested:=requested+jsonb_array_length(result);
 elsif mode='DISTANCIA' then
  lat:=nullif(p_input->>'Lat','')::double precision;lng:=nullif(p_input->>'Lng','')::double precision;rango:=nullif(p_input->>'Rango','')::double precision;busq:=p_input->>'Modo_busqueda';
  if lat is null or lng is null or lat not between -90 and 90 or lng not between -180 and 180 or rango is null or rango<=0 or busq not in ('km','min') then raise exception 'Indique coordenadas, rango y modo válidos.'; end if;
  with distances as (select d.*, 12742*asin(sqrt(least(1.0,power(sin(radians(d.latitud-lat)/2),2)+cos(radians(lat))*cos(radians(d.latitud))*power(sin(radians(d.longitud-lng)/2),2)))) km from public.e360_droguerias() d where lower(trim(d.municipio))=lower(trim(p_input->>'Ciudad')) and d.latitud between -90 and 90 and d.longitud between -180 and 180), calc as (select *,round(km::numeric,1) km_r,round(km*(select valor::text::numeric from public.parametros where clave='MINUTOS_POR_KM')+(select valor::text::numeric from public.parametros where clave='MINUTOS_BASE'))::int mins from distances) select coalesce(jsonb_agg(jsonb_build_object('Codigo',codigo,'Nombre',nombre,'Responsable',responsable,'Telefono',telefono,'Municipio',municipio,'Plan',plan,'Elegible',elegible,'Motivo',motivo,'EnBase',elegible,'Distancia_km',km_r,'Tiempo_min',mins)),'[]') into result from calc where case when busq='km' then km_r<=rango else mins<=rango end;
  missing:='[]'; requested:=jsonb_array_length(result);
 else raise exception 'Modo de segmentación inválido.'; end if;
 return jsonb_build_object('rows',result,'missing',missing,'solicitados',requested);
end $$;
create table public.asignaciones_call (usuario uuid not null references public.perfiles(id) on delete cascade, id_campana text not null references public.campanas on delete cascade, primary key(usuario,id_campana));
alter table public.asignaciones_call enable row level security;
revoke all on public.asignaciones_call from anon,authenticated;
create function public.e360_puede_campana(p_id text) returns boolean language sql stable security definer set search_path=public as $$ select public.e360_rol() in ('admin','analista') or (public.e360_rol()='call' and exists(select 1 from public.asignaciones_call where usuario=auth.uid() and id_campana=p_id)) $$;
create function public.e360_iniciar() returns jsonb language plpgsql stable security definer set search_path=public as $$
declare role text; result jsonb;
begin perform public.e360_exigir(array['admin','analista','call']); role:=public.e360_rol();
 select jsonb_build_object(
 'campanas',coalesce((select jsonb_agg(jsonb_build_object('ID',id,'Nombre',nombre,'Tipo',tipo,'Tema',tema,'Nivel',nivel,'Ciudad',ciudad,'Direccion_evento',direccion_evento,'Lat',lat,'Lng',lng,'Fecha',fecha,'Jornada',jornada,'ID_Profesional',id_profesional,'Cupos',cupos,'Modo_segmentacion',modo_segmentacion,'Rango',rango,'Modo_busqueda',modo_busqueda,'Estado',estado)) from public.campanas where public.e360_puede_campana(id)),'[]'),
 'profesionales',case when role='call' then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('ID',id,'Nombre',nombre,'Regional',regional,'Ciudad',ciudad)) from public.profesionales where activo),'[]') end,
 'droguerias',case when role='call' then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('Codigo',codigo,'Nombre',nombre,'Responsable',responsable,'Telefono',telefono,'Municipio',municipio,'Plan',plan,'Elegible',elegible,'Motivo',motivo)) from public.e360_droguerias()),'[]') end,
 'parametros',coalesce((select jsonb_object_agg(clave,case when clave='TIPIFICACIONES' then to_jsonb(valor::text) else valor end) from public.parametros),'{}'),
 'agenda',case when role='call' then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('Fecha',fecha,'Jornada',jornada,'ID_Profesional',id_profesional,'Titulo',titulo,'Estado',estado)) from public.agenda_profesional),'[]') end,
 'catalogo',case when role='call' then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('ID',id,'Nombre',nombre,'Grupo',grupo,'Meta',meta,'Activa',activa)) from public.catalogo_actividades),'[]') end,
 'cobros',case when role='call' then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('ID',id,'Fecha',fecha,'Codigo',codigo,'Concepto',concepto,'Valor',valor,'ID_Campana',id_campana,'Estado',estado)) from public.cobros),'[]') end,
 'cobertura',case when role='call' then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('Ciudad',q.municipio,'Tema',q.tema,'Nivel',q.nivel,'Cubiertas',q.cubiertas,'Base_ref',q.base_ref)) from (select d.municipio, t.tema,n.nivel,count(distinct a.codigo) cubiertas,count(distinct d.codigo) base_ref from public.droguerias d cross join unnest(array['Ventas','Finanzas','Inventarios','Marketing']) t(tema) cross join unnest(array['Básico','Intermedio','Avanzado']) n(nivel) left join public.asistencia_modulo a on a.codigo=d.codigo and a.tema=t.tema and a.nivel=n.nivel where d.municipio<>'' group by d.municipio,t.tema,n.nivel) q),'[]') end,
 'rol',role) into result; return result;
end $$;
create function public.e360_base_campana(p_id text) returns jsonb language plpgsql stable security definer set search_path=public as $$ begin perform public.e360_exigir(array['admin','analista','call']); if not public.e360_puede_campana(p_id) then raise exception 'Campaña no asignada.'; end if; return coalesce((select jsonb_agg(jsonb_build_object('ID_Campana',id_campana,'Codigo',codigo,'Nombre',nombre,'Responsable',responsable,'Telefono',telefono,'Municipio',municipio,'Observaciones',observaciones,'Tipificacion',tipificacion,'Subtipificacion',subtipificacion,'Gestionado_por',gestionado_por,'Confirma',confirma,'Asistencia',asistencia)) from public.campana_base where id_campana=p_id),'[]'); end $$;
create function public.e360_guardar_campana(p_input jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare idcamp text:=nullif(p_input->>'ID',''); prev jsonb; item jsonb; num int; cat text; begin perform public.e360_exigir(array['admin','analista']);
 perform pg_advisory_xact_lock(36001); prev:=public.e360_vista_previa(p_input); select count(*) into num from jsonb_array_elements(prev->'rows') x where (x->>'EnBase')::boolean; if num=0 then raise exception 'La base no contiene droguerías elegibles.'; end if;
 if nullif(trim(p_input->>'Nombre'),'') is null or nullif(trim(p_input->>'Ciudad'),'') is null or not exists(select 1 from public.profesionales where id=p_input->>'ID_Profesional' and activo) then raise exception 'Complete nombre, ciudad y profesional activo.'; end if;
 if idcamp is not null then
  if not exists(select 1 from public.campanas where id=idcamp) then raise exception 'Campaña no encontrada.'; end if;
  if exists(select 1 from public.campana_base where id_campana=idcamp and (tipificacion<>'' or asistencia<>'' or fecha_gestion is not null)) then raise exception 'Campaña con gestión iniciada; no se puede modificar.'; end if;
  update public.campanas set nombre=p_input->>'Nombre',tipo=p_input->>'Tipo',tema=p_input->>'Tema',nivel=p_input->>'Nivel',ciudad=p_input->>'Ciudad',direccion_evento=p_input->>'Direccion_evento',lat=nullif(p_input->>'Lat','')::float8,lng=nullif(p_input->>'Lng','')::float8,fecha=(p_input->>'Fecha')::date,jornada=p_input->>'Jornada',id_profesional=p_input->>'ID_Profesional',cupos=(p_input->>'Cupos')::int,modo_segmentacion=p_input->>'Modo_segmentacion',rango=nullif(p_input->>'Rango','')::float8,modo_busqueda=p_input->>'Modo_busqueda',actualizado=now() where id=idcamp;
  delete from public.campana_base where id_campana=idcamp; delete from public.agenda_profesional where id_campana=idcamp;
 else
  insert into public.campanas(nombre,tipo,tema,nivel,ciudad,direccion_evento,lat,lng,fecha,jornada,id_profesional,cupos,modo_segmentacion,rango,modo_busqueda) values(p_input->>'Nombre',p_input->>'Tipo',p_input->>'Tema',p_input->>'Nivel',p_input->>'Ciudad',p_input->>'Direccion_evento',nullif(p_input->>'Lat','')::float8,nullif(p_input->>'Lng','')::float8,(p_input->>'Fecha')::date,p_input->>'Jornada',p_input->>'ID_Profesional',(p_input->>'Cupos')::int,p_input->>'Modo_segmentacion',nullif(p_input->>'Rango','')::float8,p_input->>'Modo_busqueda') returning id into idcamp;
 end if;
 insert into public.campana_base(id_campana,codigo,nombre,responsable,telefono,municipio,distancia_km,tiempo_min) select idcamp,x->>'Codigo',x->>'Nombre',x->>'Responsable',x->>'Telefono',x->>'Municipio',nullif(x->>'Distancia_km','')::numeric,nullif(x->>'Tiempo_min','')::int from jsonb_array_elements(prev->'rows') x where (x->>'EnBase')::boolean;
 select id into cat from public.catalogo_actividades where nombre='Entrenamiento 360' and activa order by id limit 1;
 insert into public.agenda_profesional(id,id_profesional,fecha,jornada,catalogo_id,tipo,grupo,meta,tema,nivel,titulo,id_campana) values ('ACT-'||idcamp,p_input->>'ID_Profesional',(p_input->>'Fecha')::date,p_input->>'Jornada',cat,p_input->>'Tipo','ent','ent360',p_input->>'Tema',p_input->>'Nivel',p_input->>'Nombre',idcamp);
 return jsonb_build_object('ID',idcamp,'cantidad',num,'faltantes',prev->'missing'); end $$;
create function public.e360_eliminar_campana(p_id text) returns void language plpgsql security definer set search_path=public as $$ begin perform public.e360_exigir(array['admin','analista']); perform pg_advisory_xact_lock(36001); if exists(select 1 from public.campana_base where id_campana=p_id and (tipificacion<>'' or asistencia<>'' or fecha_gestion is not null)) then raise exception 'Campaña con gestión iniciada.'; end if; delete from public.campanas where id=p_id; if not found then raise exception 'Campaña no encontrada.'; end if; end $$;
create function public.e360_guardar_gestion(p_input jsonb) returns void language plpgsql security definer set search_path=public as $$
declare camp public.campanas; oldrow public.campana_base; tip text:=p_input->>'Tipificacion'; sub text:=p_input->>'Subtipificacion'; conf text:=p_input->>'Confirma'; asist text:=coalesce(p_input->>'Asistencia',''); choices jsonb;
begin perform public.e360_exigir(array['admin','analista','call']); perform pg_advisory_xact_lock(36001);
 if not public.e360_puede_campana(p_input->>'ID_Campana') then raise exception 'Campaña no asignada.'; end if;
 select * into camp from public.campanas where id=p_input->>'ID_Campana'; select * into oldrow from public.campana_base where id_campana=camp.id and codigo=p_input->>'Codigo' for update; if oldrow.codigo is null then raise exception 'Contacto no encontrado.'; end if;
 select valor into choices from public.parametros where clave='TIPIFICACIONES'; if not coalesce((choices->tip) ? sub,false) or conf not in ('Pendiente','Sí','No') or asist not in ('','Asistió','No asistió') then raise exception 'Gestión inválida.'; end if;
 if oldrow.asistencia<>'' and oldrow.asistencia<>asist then raise exception 'La asistencia ya registrada requiere revisión administrativa.'; end if;
 update public.campana_base set tipificacion=tip,subtipificacion=sub,observaciones=coalesce(p_input->>'Observaciones',''),gestionado_por=coalesce(p_input->>'Gestionado_por',''),confirma=conf,asistencia=asist,fecha_gestion=now() where id_campana=camp.id and codigo=oldrow.codigo;
 if asist='Asistió' then insert into public.asistencia_modulo(codigo,tema,nivel,id_campana,fecha) values(oldrow.codigo,camp.tema,camp.nivel,camp.id,camp.fecha) on conflict(codigo,tema,nivel) do nothing; end if;
end $$;
create function public.e360_evaluar_post_evento(p_id text) returns integer language plpgsql security definer set search_path=public as $$
declare c public.campanas; cantidad int:=0; n int;
begin perform public.e360_exigir(array['admin','analista']); perform pg_advisory_xact_lock(36001); select * into c from public.campanas where id=p_id; if c.id is null then raise exception 'Campaña no encontrada.'; end if; if c.fecha>(now() at time zone 'America/Bogota')::date then raise exception 'La campaña aún no ha ocurrido.'; end if;
 insert into public.cobros(codigo,concepto,valor,id_campana) select b.codigo,'Inasistencia',(select valor::text::numeric from public.parametros where clave='COBRO_INASISTENCIA'),p_id from public.campana_base b where b.id_campana=p_id and b.confirma='Sí' and b.asistencia='No asistió' on conflict(codigo,concepto,id_campana) do nothing; get diagnostics n=row_count; cantidad:=cantidad+n;
 insert into public.cobros(codigo,concepto,valor,id_campana) select b.codigo,'Proceso incompleto',(select valor::text::numeric from public.parametros where clave='COBRO_INCOMPLETO'),p_id from public.campana_base b where b.id_campana=p_id and b.asistencia='Asistió' and not exists(select 1 from public.planes p where p.codigo=b.codigo and lower(trim(p.modulo))=lower(trim(c.tema)) and lower(trim(p.nivel))=lower(trim(c.nivel)) and lower(trim(p.estado_general))='cerrado') on conflict(codigo,concepto,id_campana) do nothing; get diagnostics n=row_count; return cantidad+n;
end $$;
revoke execute on function public.e360_rol(),public.e360_exigir(text[]),public.e360_droguerias(),public.e360_puede_campana(text),public.e360_iniciar(),public.e360_vista_previa(jsonb),public.e360_guardar_campana(jsonb),public.e360_eliminar_campana(text),public.e360_base_campana(text),public.e360_guardar_gestion(jsonb),public.e360_evaluar_post_evento(text) from public,anon,authenticated;
grant execute on function public.e360_iniciar(),public.e360_vista_previa(jsonb),public.e360_guardar_campana(jsonb),public.e360_eliminar_campana(text),public.e360_base_campana(text),public.e360_guardar_gestion(jsonb),public.e360_evaluar_post_evento(text) to authenticated;
